class Solution {
    string input;
    int pos = 0;

    void spaces() {
        while (pos < static_cast<int>(input.size()) && input[pos] == ' ') {
            ++pos;
        }
    }

    long long factor() {
        spaces();
        int sign = 1;
        while (pos < static_cast<int>(input.size())
               && (input[pos] == '+' || input[pos] == '-')) {
            if (input[pos] == '-') {
                sign = -sign;
            }
            ++pos;
            spaces();
        }
        long long value = 0;
        if (input[pos] == '(') {
            ++pos;
            value = expression();
            spaces();
            ++pos;
        } else {
            while (pos < static_cast<int>(input.size())
                   && isdigit(input[pos])) {
                value = value * 10 + (input[pos++] - '0');
            }
        }
        return sign * value;
    }

    long long term() {
        long long value = factor();
        while (true) {
            spaces();
            if (pos >= static_cast<int>(input.size())
                || (input[pos] != '*' && input[pos] != '/')) {
                return value;
            }
            char op = input[pos++];
            long long rhs = factor();
            value = (op == '*') ? value * rhs : value / rhs;
        }
    }

    long long expression() {
        long long value = term();
        while (true) {
            spaces();
            if (pos >= static_cast<int>(input.size())
                || (input[pos] != '+' && input[pos] != '-')) {
                return value;
            }
            char op = input[pos++];
            long long rhs = term();
            value = (op == '+') ? value + rhs : value - rhs;
        }
    }

public:
    int calculate(string s) {
        input = s;
        pos = 0;
        return static_cast<int>(expression());
    }
};
